"""Targeted frame-mutation fuzz: classification counters must agree exactly."""
import random
import struct
import sys

sys.path.insert(0, '/workspace/project')
sys.path.insert(0, '/workspace/dev')
import ref            # noqa
import harness        # noqa
import fuzz           # noqa
from wire import packet as build_packet, seal  # noqa

MASK = (1 << 24) - 1


def mutate(rng, frame, D, K, start, rank):
    """Return (frame, rank) after one targeted mutation."""
    f = bytearray(frame)
    kind = rng.randrange(22)
    if kind == 0:
        f[12] = rng.choice([0x08, 0x86, 0x00])          # ethertype
        f[13] = rng.choice([0x00, 0x01, 0xdd])
    elif kind == 1:
        f[14] = rng.choice([0x45, 0x46, 0x55, 0x05, 0x44])  # version/ihl
    elif kind == 2:
        f[15] = rng.randrange(256)                       # tos (free)
    elif kind == 3:
        n = rng.randrange(65536)
        f[16], f[17] = n >> 8, n & 0xff                  # total length
    elif kind == 4:
        f[20], f[21] = rng.choice([(0x20, 0x00), (0x40, 0x01), (0x00, 0x01),
                                   (0x60, 0x00), (0x40, 0x00), (0x00, 0x00)])
    elif kind == 5:
        f[22] = rng.randrange(256)                       # ttl (free)
    elif kind == 6:
        f[23] = rng.choice([6, 0, 17, 255])              # protocol
    elif kind == 7:
        f[24] ^= 1 << rng.randrange(8)                   # ip checksum
    elif kind == 8:
        f[rng.randrange(26, 34)] = rng.randrange(256)    # src/dst IP
    elif kind == 9:
        f[rng.randrange(34, 38)] = rng.randrange(256)    # ports
    elif kind == 10:
        n = rng.randrange(65536)
        f[38], f[39] = n >> 8, n & 0xff                  # udp length
    elif kind == 11:
        f[rng.randrange(40, 42)] = rng.randrange(256)    # udp checksum
    elif kind == 12:
        f[42] = rng.choice([0x00, 0x01, 0x04, 0x05, 0x10, 0x11, 0x12, 0xff])
    elif kind == 13:
        f[43] = rng.randrange(256)                       # flags/pad byte
    elif kind == 14:
        f[rng.randrange(44, 46)] = rng.randrange(256)    # pkey
    elif kind == 15:
        f[rng.randrange(46, 50)] = rng.randrange(256)    # qpn
    elif kind == 16:
        f[rng.randrange(50, 54)] = rng.randrange(256)    # apsn
    elif kind == 17 and len(f) > 54:
        f[54] = rng.randrange(256)                       # aeth top / payload
    elif kind == 18:
        f = f[:rng.randrange(0, len(f))]                 # truncate
    elif kind == 19:
        f += bytes(rng.randrange(256) for _ in range(rng.randrange(1, 9)))
    elif kind == 20:
        f[-1 - rng.randrange(4)] ^= rng.randrange(1, 256)   # icrc
    else:
        f[rng.randrange(6, 12)] = rng.randrange(256)     # MACs
    return bytes(f), rank


def gen_case(rng):
    prim = rng.choice(['allreduce', 'reduce', 'broadcast', 'barrier',
                       'allgather', 'reducescatter'])
    if prim == 'barrier':
        K, D = 1, 0
    else:
        K = rng.randrange(1, 9)
        D = rng.choice([1, 2, 4])
        if prim == 'reducescatter':
            K = 4 * rng.randrange(1, 3)
    N = rng.randrange(1, 6)
    start = rng.choice([0, 5, (1 << 24) - 2, rng.randrange(1 << 24)])
    events = []
    for _ in range(rng.randrange(1, 40)):
        r = rng.randrange(4)
        style = rng.random()
        if style < 0.55:
            p = rng.randrange(K)
            body = struct.pack('!%dI' % D, *[rng.randrange(1 << 32) for _ in range(D)])
            frame = build_packet(r, (start + p) & MASK, body)
        elif style < 0.8:
            n = rng.randrange(0, 3 * K + 2)
            frame = build_packet(r, (start + n - 1) & MASK, ack=True)
        else:
            frame = build_packet(rng.randrange(4), rng.randrange(1 << 24),
                                 struct.pack('!%dI' % D,
                                             *[rng.randrange(1 << 32) for _ in range(D)]))
        frame, port = mutate(rng, frame, D, K, start, r)
        if rng.random() < 0.3:
            port = rng.randrange(4)
        events.append({'op': 'wire', 'rank': port, 'hex': frame.hex()})
        if rng.random() < 0.25:
            events.append(rng.choice([{'op': 'flush'}, {'op': 'retry', 'rank': rng.randrange(4)},
                                      {'op': 'snap', 'tag': 't'}, {'op': 'budget',
                                      'n': rng.choice([-1, 0, 1, 4])}]))
    return {'primitive': prim, 'mode': rng.choice([2, 3]), 'root': rng.randrange(4),
            'segments': K, 'words': D, 'capacity': N, 'start': start,
            'events': events, 'trace': rng.choice([0, 2, 32])}


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 50
    rng = random.Random(seed)
    bad = 0
    for it in range(rounds):
        cases = [gen_case(rng) for _ in range(rng.randrange(1, 4))]
        want = [ref.run(c) for c in cases]
        got = harness.solve(cases)['cases']
        for i, (g, w) in enumerate(zip(got, want)):
            out = []
            fuzz.diff('c%d' % i, g, w, out)
            if out:
                bad += 1
                print('MISMATCH seed=%d iter=%d case=%d' % (seed, it, i), flush=True)
                import json
                print(json.dumps(cases[i])[:2500], flush=True)
                for p, gv, wv in out[:14]:
                    print('   ', p, 'got=', str(gv)[:150], 'want=', str(wv)[:150], flush=True)
                json.dump(cases[i], open('/workspace/tmp/wbad_%d_%d.json' % (seed, it), 'w'), indent=1)
                if bad > 3:
                    return 1
    print('done wirefuzz seed=%d iters=%d bad=%d' % (seed, it + 1, bad))
    return 1 if bad else 0


if __name__ == '__main__':
    raise SystemExit(main())
